// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // test contract is C's owner (deployer) and must be able to receive withdrawn ETH
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint128).max);

        // fund the test contract (the owner), then deposit into c via fallback
        vm.deal(address(this), amount);
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok, "deposit failed");

        // owner (this contract) withdraws everything
        c.withdrawAll();

        assertTrue(address(c).balance == 0);
    }
}
